@IsTest private class SchemaClassificationObservation {
 private static Object listType(List<SObject> rows) {
  Schema.SObjectType token=rows.getSObjectType();
  return token==null?null:token.getDescribe().getName();
 }
 private static List<SObject> fromIds(Iterable<Id> ids) {
  List<SObject> records=new List<SObject>();
  for(Id key:ids)records.add(key.getSObjectType().newSObject(key));
  return records;
 }
 @IsTest static void lists() {
  List<User> concrete=[SELECT Id FROM User LIMIT 2];
  Map<Id,User> keyed=new Map<Id,User>(concrete);
  List<Id> ids=new List<Id>(keyed.keySet());
  List<SObject> listRows=fromIds(ids);
  List<SObject> setRows=fromIds(keyed.keySet());
  List<SObject> singleton=fromIds(new List<Id>{UserInfo.getUserId()});
  List<SObject> doubled=fromIds(new List<Id>{UserInfo.getUserId(),UserInfo.getUserId()});
  List<User> typed=new List<User>{(User)User.SObjectType.newSObject(UserInfo.getUserId())};
  List<SObject> widened=typed;
  Map<String,Object> out=new Map<String,Object>{'count'=>ids.size(),'list'=>listType(listRows),'set'=>listType(setRows),'singleton'=>listType(singleton),'double'=>listType(doubled),'typed'=>listType(widened),'element'=>singleton[0].getSObjectType().getDescribe().getName(),'populated'=>singleton[0].getPopulatedFieldsAsMap().keySet()};
  System.assertEquals('CLASS_NATIVE',JSON.serialize(out));
 }
 private static Map<String,Object> idType(Schema.SObjectType token,Integer width) {
  String prefix=token.getDescribe().getKeyPrefix();
  String raw=prefix+'0'.repeat(width-prefix.length()-1)+'1';
  Map<String,Object> out=new Map<String,Object>{'prefix'=>prefix,'length'=>raw.length()};
  try {Id key=Id.valueOf(raw);out.put('token',key.getSObjectType().getDescribe().getName());}
  catch(Exception failure){out.put('exception',failure.getTypeName());out.put('message',failure.getMessage());}
  return out;
 }
 @IsTest static void templateId() {
  Integer width=CaseComment.SObjectType.getDescribe().fields.getMap().get('Id').getDescribe().getLength();
  Map<String,Object> out=new Map<String,Object>{'width'=>width,'short'=>idType(CaseComment.SObjectType,15),'described'=>idType(CaseComment.SObjectType,width),'standard'=>idType(User.SObjectType,width),'instance'=>new CaseComment().getSObjectType().getDescribe().getName()};
  System.assertEquals('CLASS_NATIVE',JSON.serialize(out));
 }
}

