@IsTest private class IdClassificationObservation {
 private static Map<String,Object> lookup(Id key) {
  Map<String,Object> out=new Map<String,Object>{'id'=>String.valueOf(key)};
  try {out.put('token',key.getSObjectType().getDescribe().getName());}
  catch(Exception failure){out.put('exception',failure.getTypeName());out.put('message',failure.getMessage());}
  return out;
 }
 private static Object implicit(String raw) {
  try {Id key=raw;return lookup(key);}
  catch(Exception failure){return new Map<String,Object>{'exception'=>failure.getTypeName(),'message'=>failure.getMessage()};}
 }
 private static Object argument(String raw) {
  try {return lookup(raw);}
  catch(Exception failure){return new Map<String,Object>{'exception'=>failure.getTypeName(),'message'=>failure.getMessage()};}
 }
 @IsTest static void observe() {
  String prefix=CaseComment.SObjectType.getDescribe().getKeyPrefix();
  Integer width=CaseComment.SObjectType.getDescribe().fields.getMap().get('Id').getDescribe().getLength();
  String shortText=prefix+'0'.repeat(11)+'1';
  Id shortId=shortText;
  String longText=String.valueOf(shortId);
  String padded=prefix+'0'.repeat(width-prefix.length()-1)+'1';
  Case parent=new Case(Subject='Owned type observation',Status='New',Origin='Web');insert parent;
  CaseComment child=new CaseComment(ParentId=parent.Id,CommentBody='Owned type observation');insert child;
  System.assertEquals('ID_NATIVE',JSON.serialize(new Map<String,Object>{'short'=>implicit(shortText),'canonical'=>implicit(longText),'padded'=>implicit(padded),'argument'=>argument(padded),'stored'=>lookup(child.Id),'user'=>lookup(UserInfo.getUserId())}));
 }
}

